        honor: { upright: {"a":["신선한 시도와 참신한 아이디어로 주목받을 수 있는 시기입니다.","남들이 잘 안 쓰는 방식을 시도한 것이 눈에 띄는 시기입니다.","예상 밖의 과감한 행동이 뜻밖에 큰 호응을 얻을 수 있는 상황입니다."],"b":["남들과 다른 방식으로 접근한 것이 오히려 좋은 평가로 이어질 수 있어요.","정해진 틀을 벗어난 시도가 사람들의 기억에 오래 남을 수 있습니다.","낯설게만 보였던 접근이 뜻밖에 화제를 모으며 이름을 알리는 계기가 됩니다."]}, reversed: {"a":["경솔한 언행으로 평판에 흠이 갈 수 있는 시기입니다.","작은 실언 하나가 주변의 신뢰를 은근히 흔들어 놓을 수 있어요.","깊이 생각하지 않은 행동이 구설수로 번질 수 있는 상황입니다."],"b":["즉흥적으로 내뱉은 말이 생각보다 오래 남을 수 있으니 신중하게 행동하세요.","입 밖으로 내기 전에 한 번 더 되새겨보는 습관을 들이세요.","사소해 보이는 언행도 주변에서는 크게 기억할 수 있으니 조심하세요."]} },
        moving: { upright: {"a":["즉흥적인 이사나 이동이 새로운 활력을 줄 수 있는 시기입니다.","예정에 없던 거처로 옮기는 일이 뜻밖의 활기를 가져다줄 수 있습니다.","가벼운 마음으로 알아본 동네가 의외로 마음에 쏙 들 수 있는 시기입니다."],"b":["계획에 없던 곳이라도 막상 가보면 의외로 잘 맞을 수 있어요.","후보에 없던 지역도 한번 직접 둘러보면 좋은 선택이 될 수 있습니다.","너무 재지 말고 발품을 팔아보면 뜻밖의 좋은 곳을 만날 수 있어요."]}, reversed: {"a":["충분한 계획 없이 이동했다가 불편을 겪을 수 있는 시기입니다.","꼼꼼히 알아보지 않고 옮긴 곳에서 생활이 불편해질 수 있는 시기입니다.","서둘러 정한 거처가 막상 살아보니 기대와 다를 수 있는 시기입니다."],"b":["성급하게 결정하기보다 조건을 한 번 더 확인해보세요.","계약 전에 주변 환경을 직접 살펴보고 결정하세요.","계약 서류의 세부 사항을 놓치지 말고 다시 살펴보세요."]} },
        children: { upright: {"a":["아이와 함께 새로운 것을 시도하기 좋은 시기입니다.","낯선 장소나 체험을 찾아 나서면 아이의 눈이 반짝이는 시기입니다.","평소와 다른 나들이가 아이에게 특별한 기억으로 남을 수 있는 시기입니다."],"b":["낯선 활동이라도 아이와 함께라면 즐거운 추억이 될 수 있어요.","낯설어하는 아이 옆에서 함께해주는 것만으로도 큰 힘이 됩니다.","작은 모험 같은 하루가 아이와의 사이를 더 가깝게 만들어줍니다."]}, reversed: {"a":["아이에 대한 준비 부족으로 어려움을 겪을 수 있는 시기입니다.","빠뜨린 채비 때문에 아이와 함께 곤란한 상황에 놓일 수 있어요.","필요한 것을 놓친 채로 나섰다가 아이가 힘들어할 수 있는 시기입니다."],"b":["즉흥적인 결정보다 아이의 상황을 한 번 더 살펴보세요.","나서기 전에 아이에게 필요한 것들을 한 번 더 챙겨보세요.","아이의 컨디션과 기분을 먼저 살핀 뒤에 계획을 정하세요."]} }
