        honor: { upright: {"a":["은근한 신뢰와 존경을 얻는 조용하지만 단단한 시기입니다.","말없이 쌓아온 신망이 조금씩 드러나는 단단한 시기입니다.","애써 알리지 않아도 주변에서 먼저 알아주는 시기입니다."],"b":["드러내지 않아도 진가를 알아보는 사람이 있을 거예요.","말하지 않아도 마음 씀씀이를 알아채는 이가 곁에 있기 마련입니다.","떠들지 않아도 꾸준한 태도가 결국 인정을 받게 됩니다."]}, reversed: {"a":["알려지지 않은 문제가 뒤늦게 드러나며 평판에 그림자가 질 수 있는 시기이니 미리 살펴보세요.","감춰뒀던 사정이 뒤늦게 새어 나오며 이미지에 흠이 갈 수 있어요.","묻어두었던 일이 불거지면서 평판이 순식간에 흔들릴 수 있습니다."],"b":["숨기고 있던 부분이 있다면 스스로 먼저 정리해두는 것이 안전합니다.","마음에 걸리는 일이 있을 때 이번 기회에 스스로 털어내 보세요.","감추려 하기보다 미리 솔직하게 밝히는 쪽이 안전합니다."]} },
        moving: { upright: {"a":["직감을 따라 결정한 곳이 의외로 좋은 자리로 이어지는 시기입니다.","이유는 설명하기 어려워도 마음이 가는 곳으로 향하면 좋은 결과를 얻는 시기입니다.","촉이 이끄는 대로 고른 장소가 결국 딱 맞아떨어지는 시기입니다."],"b":["논리적인 이유가 부족해도 마음이 끌리는 곳을 믿어볼 만합니다.","따지기보다 왠지 편안하게 느껴지는 쪽으로 마음을 정해보세요.","설명이 안 돼도 자꾸 눈길이 가는 방향을 따라가보는 것도 좋습니다."]}, reversed: {"a":["확신 없는 상태로 이동을 결정하면 나중에 혼란스러움을 느낄 수 있습니다.","마음이 정리되지 않은 채로 이사를 서두르면 뒤늦게 후회할 수 있어요.","확실한 느낌 없이 계약을 진행했다가 예상 못한 불편을 겪을 수 있어요."],"b":["결정을 서두르기보다 마음이 정리될 때까지 기다려보세요.","서두르지 말고 마음이 편안해지는 곳을 다시 찾아보세요.","확신이 들지 않는다면 계약을 잠시 미뤄두는 것도 방법입니다."]} },
        children: { upright: {"a":["말하지 않아도 아이의 마음을 직관적으로 알아채는 섬세한 시기입니다.","굳이 묻지 않고도 원하는 것을 먼저 알아차리게 되는 시기입니다.","말보다 스치는 표정 하나로 마음결을 짚어내는 시기입니다."],"b":["아이가 표현하지 않은 감정까지 세심하게 헤아려주면 관계가 더 깊어집니다.","말로 다 하지 않는 작은 신호도 놓치지 말고 살펴봐주세요.","표현이 서툰 순간에도 아이의 마음을 먼저 헤아려주세요."]}, reversed: {"a":["아이가 보내는 신호를 놓치고 지나갈 수 있으니 조금 더 세심하게 살펴보세요.","아이의 작은 변화를 못 보고 지나치면 서운함이 쌓일 수 있어요.","정신없이 바쁜 하루 속에서 중요한 낌새를 놓칠 수 있습니다."],"b":["바쁘더라도 아이의 표정과 행동에 잠깐이라도 관심을 기울여보세요.","짧은 순간이라도 아이와 눈을 맞추고 마음을 살펴봐주세요.","짬이 나는 대로 곁에서 눈빛을 자세히 들여다봐주세요."]} }
