          upright: { jobseek: {"a":["따뜻하고 포용력 있는 태도가 면접이나 만남에서 좋은 인상을 남기는 시기입니다.","사람을 편안하게 만드는 분위기가 면접장에서 좋은 점수로 이어질 수 있습니다.","이력서보다 사람 자체에서 느껴지는 편안함이 면접관에게 신뢰를 주는 시기입니다."],"b":["꾸며낸 모습보다 자연스러운 편안함이 오히려 더 좋은 평가로 이어집니다.","겉치레를 걷어낸 소탈한 태도가 면접관에게 좋은 점수를 안겨줄 수 있습니다.","딱딱한 격식보다 편안한 말투 하나가 더 좋은 기억으로 남습니다."]}, switch: {"a":["새로운 자리에서 그동안 쌓아온 역량이 자연스럽게 꽃피는 시기입니다.","옮겨간 자리에서 묵혀둔 능력이 뜻밖에 빛을 발하는 시기입니다.","새 환경에서 그간의 경험이 순조롭게 녹아드는 시기입니다."],"b":["겸손한 태도로 임하면 실력뿐 아니라 주변의 신뢰까지 함께 따라올 수 있어요.","나서서 드러내기보다 묵묵히 실력으로 보여주는 편이 좋습니다.","낮은 자세로 배우려는 모습이 새로운 자리에서 든든한 평판을 만들어줍니다."]} },
          reversed: { jobseek: {"a":["안주하려는 마음에 적극성이 부족해 기회를 놓칠 수 있는 시기입니다.","지금 자리가 편하다는 이유로 다른 기회 쪽으로는 눈길도 주지 않게 됩니다.","움직이기 귀찮은 기분에 좋은 제안조차 흘려보내게 됩니다."],"b":["편안함에 안주하기보다 조금 더 적극적으로 움직여볼 필요가 있습니다.","익숙한 자리에 머무르기보다 한 걸음 더 나서보는 용기가 필요합니다.","미루는 습관을 버리고 관심 있는 곳에 먼저 연락해보세요."]}, switch: {"a":["새 환경에 대한 불안으로 변화를 미루며 제자리에 머무를 수 있습니다.","낯선 조직에서의 부담이 커지며 결정을 자꾸 뒤로 미루게 됩니다.","밀려오는 부담감에 눌려 제안 앞에서 선뜻 답을 내놓지 못하게 됩니다."],"b":["익숙함을 벗어나는 것이 두렵더라도 조금씩 시도해보는 용기가 필요합니다.","두려움을 완전히 없애려 하기보다 작은 걸음부터 떼어보세요.","마음의 준비가 다 되지 않았어도 일단 발을 내디뎌보는 편이 좋습니다."]} }
