          reversed: { team: {"a":["나태한 태도가 팀 분위기나 평가에 영향을 줄 수 있는 시기입니다.","눈에 띄지 않게 지내는 날들이 이어지며 존재감이 점점 옅어질 수 있는 시기입니다.","편한 대로 미뤄둔 협업이 팀의 진행 속도를 늦추게 됩니다."],"b":["회의나 업무 공유 자리에서만이라도 목소리를 조금 더 내보세요.","눈에 띄지 않더라도 맡은 몫만큼은 확실하게 드러내 보세요.","뒤로 물러나 있기보다 의견을 적극적으로 나눠보는 것이 좋습니다."]}, personal: {"a":["느슨해진 마음가짐이 업무 성과 저하로 이어질 수 있습니다.","편한 대로 흘러가는 태도가 결국 크고 작은 실수로 번질 수 있어요.","여유로움에 젖어 마감 기한을 자꾸 놓치는 습관이 슬며시 자리 잡을 수 있어요."],"b":["다시 긴장감을 챙기고 업무 습관을 점검해보세요.","느슨해진 일정표를 다시 촘촘하게 정리해보세요.","미뤄둔 일이 있다면 지금부터라도 순서를 정해 처리해보세요."]} }
