        honor: { upright: {"a":["인간적인 매력과 포용력으로 자연스럽게 좋은 평판을 얻는 시기입니다.","넉넉한 인품이 자연스레 주변의 좋은 평가로 이어지는 시기입니다.","편안하게 다가가는 태도가 뜻밖의 좋은 소문으로 번지는 시기입니다."],"b":["꾸미지 않은 따뜻함이 사람들의 마음을 편안하게 만들어줍니다.","애써 드러내지 않아도 사람 좋은 인상이 오래도록 남습니다.","포용하는 마음 씀씀이가 시간이 갈수록 좋은 평판으로 쌓여갑니다."]}, reversed: {"a":["나태하거나 안주하려는 태도가 평판에 부정적인 영향을 줄 수 있습니다.","느슨해진 언행이 주변의 신뢰를 조금씩 갉아먹게 됩니다.","편한 대로 넘기는 습관이 뜻하지 않게 실망으로 비칠 수 있는 시기입니다."],"b":["편안함에 머무르기보다 조금 더 성실한 모습을 보여줄 필요가 있습니다.","사소한 부분이라도 조금 더 꼼꼼하게 신경 써보세요.","미루는 모습보다 책임지는 태도를 보여주는 것이 평판에 도움이 됩니다."]} },
        moving: { upright: {"a":["더 안락하고 풍요로운 곳으로의 이동이 순조롭게 이루어지는 시기입니다.","넉넉하고 포근한 느낌의 장소로 자리를 옮기게 되는 시기입니다.","살기 편한 동네를 찾아 옮기는 일이 무리 없이 성사되는 시기입니다."],"b":["조건을 너무 꼼꼼히 따지기보다 마음이 편안해지는 공간인지를 기준으로 골라보세요.","세세한 조건보다 머물렀을 때의 편안한 느낌을 먼저 살펴보세요.","직접 둘러보며 몸으로 느껴지는 분위기를 살펴보고 마음 가는 곳을 정해보세요."]}, reversed: {"a":["안주하려는 마음에 필요한 이동을 계속 미루고 있을 수 있습니다.","지금 사는 곳이 편하다는 이유로 이동 계획 자체를 자꾸 미루게 됩니다.","귀찮은 기분이 앞서 꼭 해야 할 채비조차 손을 놓아버릴 수 있어요."],"b":["편안함에 안주하기보다 필요한 변화를 받아들이는 용기가 필요합니다.","더 미루지 말고 지금부터 필요한 절차를 하나씩 밟아보세요.","정든 곳을 떠나는 아쉬움이 있어도 지금은 움직여야 할 때임을 받아들여보세요."]} },
        children: { upright: {"a":["아이와 풍요롭고 따뜻한 시간을 보내며 유대가 깊어지는 시기입니다.","넉넉한 품으로 아이를 감싸주며 서로의 사이가 더 가까워지는 시기입니다.","아이와 나누는 소소한 놀이가 다정한 추억으로 쌓여가는 시기입니다."],"b":["작은 관심과 애정이 아이와의 유대를 더욱 깊게 만들어줍니다.","다정한 눈빛 하나가 아이 마음속 깊이 안정감을 심어줍니다.","곁에서 함께해주는 시간 자체가 아이에게는 가장 큰 선물이 됩니다."]}, reversed: {"a":["과잉보호가 오히려 아이의 성장 기회를 막고 있을 수 있으니 돌아보세요.","모든 것을 대신해주려는 마음이 아이의 자립을 더디게 만들 수 있습니다.","지나치게 감싸는 태도가 스스로 부딪혀볼 도전의 문을 좁힐 수 있어요."],"b":["아이가 스스로 해볼 기회를 조금씩 열어주는 것이 좋습니다.","실수하더라도 스스로 해결해볼 여지를 남겨주세요.","한 걸음 물러서서 아이가 시도하는 모습을 지켜봐주세요."]} }
