          upright: { solo: {"a":["안정감 있고 책임감 있는 태도가 진지한 만남으로 이어질 수 있는 시기입니다.","믿음직한 인상을 주는 상대와 자연스럽게 가까워질 수 있는 때입니다.","흔들림 없는 성실함이 매력으로 다가가 좋은 만남을 이끌어냅니다."],"b":["가벼운 만남보다 진지하게 책임지려는 태도가 좋은 인연을 부릅니다.","장난스러운 접근보다 진심이 느껴지는 모습이 더 오래 기억에 남습니다.","허투루 대하지 않는 마음가짐이 상대의 마음을 서서히 움직입니다."]}, couple: {"a":["관계에 확실한 방향과 약속을 세우면 신뢰가 더 단단해지는 시기입니다.","앞으로의 계획을 분명히 나누는 대화가 사이를 더 굳건하게 만듭니다.","다음 단계에 대한 이야기를 미루지 않는 태도가 사이를 한결 견고하게 다져줍니다."],"b":["애매하게 넘기지 말고 구체적인 계획을 함께 세워보세요.","구체적으로 정하지 않은 부분이 있다면 이번 기회에 두 사람이 함께 못 박아두세요.","대충 얼버무리지 않고 서로 확인한 내용을 하나씩 실천해보세요."]} },
