        honor: { upright: {"a":["확고한 리더십으로 주변의 신뢰와 존경을 얻는 시기입니다.","흔들림 없는 결단력이 주변의 인정을 이끌어내는 시기입니다.","중심 잡힌 모습이 사람들 사이에서 자연스러운 권위로 자리 잡는 시기입니다."],"b":["책임을 다하는 모습이 자연스럽게 존경으로 이어집니다.","말보다 행동으로 증명하는 자세가 사람들의 인정을 이끌어냅니다.","한결같이 책임지는 태도가 시간이 갈수록 신망을 쌓아줍니다."]}, reversed: {"a":["독선적이고 권위적인 태도가 평판을 해칠 수 있으니 조심하세요.","자기 뜻만 고집하는 모습이 주변의 불만을 살 수 있는 시기입니다.","지나친 강경함이 평판에 은근한 흠집을 남길 수 있습니다."],"b":["다른 사람의 의견도 존중하는 모습을 보여줄 필요가 있습니다.","목소리를 낮추고 주변의 말에 귀 기울여보세요.","강하게 밀어붙이기보다 한 발 물러서는 여유를 보여주세요."]} },
        moving: { upright: {"a":["안정적인 기반을 갖춘 곳으로 계획에 따라 이동하는 시기입니다.","탄탄하게 준비된 절차를 따라 이사가 매끄럽게 진행되는 시기입니다.","조건을 꼼꼼히 따져 고른 장소로 순조롭게 옮겨가는 시기입니다."],"b":["세운 계획대로 차근차근 준비하면 순조롭게 진행됩니다.","정해둔 일정표대로 하나씩 짚어가며 준비해보세요.","미리 세운 체크리스트를 빠짐없이 확인하며 진행해보세요."]}, reversed: {"a":["원칙만 고집하다 유연하게 대응해야 할 이동 기회를 놓칠 수 있습니다.","처음 세운 기준만 붙들다 보면 좋은 매물을 놓치게 됩니다.","지나치게 까다로운 조건을 고집하다 이사 시기를 자꾸 미루게 될 수 있어요."],"b":["정해둔 조건을 조금 완화하는 유연함이 필요할 수 있습니다.","몇 가지 기준은 내려놓고 조금 더 넓게 알아보세요.","완벽한 조건을 찾기보다 적당한 선에서 결정해보세요."]} },
        children: { upright: {"a":["원칙 있는 태도로 아이에게 든든한 울타리가 되어주는 시기입니다.","한결같은 모습으로 곁을 지켜주는 부모가 아이에게 큰 힘이 되는 시기입니다.","정해둔 규칙을 하나씩 지켜나가는 일상이 아이에게 잔잔한 안정감을 전해줍니다."],"b":["일관된 태도가 아이에게 안정감을 심어줍니다.","정한 규칙을 끝까지 지키는 모습이 아이에게 본보기가 됩니다.","말과 행동이 한결같은 부모의 모습이 든든한 의지처가 되어줍니다."]}, reversed: {"a":["지나치게 엄격한 태도가 아이에게 부담과 반발을 불러올 수 있습니다.","너무 꽉 짜인 규율이 아이를 숨 막히게 할 수 있는 시기입니다.","융통성 없는 잣대가 아이와의 사이에 조금씩 벽을 만들게 됩니다."],"b":["규칙을 지키게 하되 아이의 마음도 헤아려주는 균형이 필요합니다.","정해둔 틀보다 아이가 느끼는 감정을 먼저 살펴봐주세요.","엄격함 속에서도 다정한 대화를 잊지 않는 것이 중요합니다."]} }
