          reversed: { consumption: {"a":["관습적인 소비 습관만 고집하다 더 나은 선택을 놓칠 수 있습니다.","늘 하던 대로만 쓰다 보면 더 나은 조건을 지나칠 수 있는 시기입니다.","오래된 소비 패턴에서 벗어나지 못해 손해를 볼 수 있는 시기입니다."],"b":["익숙한 방식만 고집하지 말고 다른 대안도 살펴보세요.","가끔은 새로운 소비처도 한번 시도해보세요.","비교해보지 않고 늘 가던 곳만 찾는 습관을 점검해보세요."]}, invest: {"a":["새로운 방식을 거부하다 변화하는 시장에서 뒤처질 수 있는 시기입니다.","익숙한 종목만 고집하다 달라진 흐름을 놓치는 시기일 수 있습니다.","낯선 종목을 외면하다 값진 기회를 눈앞에서 놓치고 맙니다."],"b":["낯선 방식이라도 열린 마음으로 검토해볼 필요가 있습니다.","낯설다는 이유만으로 기회를 밀어내지 않도록 해보세요.","새로운 정보에도 마음을 열고 한번쯤 살펴보세요."]} }
