        honor: { upright: {"a":["전통적인 방식으로 인정받는 시기입니다.","오래도록 이어온 방식을 지키는 모습이 좋은 평판으로 이어지는 시기입니다.","정도를 걷는 태도가 시간이 지날수록 좋은 평가를 받는 시기입니다."],"b":["검증된 방식을 성실히 따르는 태도가 꾸준한 신뢰로 이어집니다.","원칙을 지키는 모습이 사람들의 믿음을 서서히 쌓아줍니다.","한결같이 성실한 태도가 오래도록 좋은 이름을 남겨줍니다."]}, reversed: {"a":["관습에 얽매인 태도가 평판에 부담이 될 수 있습니다.","지나치게 격식을 따지는 모습이 답답한 인상을 남길 수 있는 시기입니다.","낡은 방식만 고집하는 모습이 사람들 사이에서 부정적으로 비치게 됩니다."],"b":["때로는 정해진 틀에서 벗어난 유연한 모습도 필요합니다.","가끔은 예상 밖의 참신한 모습을 보여주는 것도 좋습니다.","격식을 조금 내려놓으면 오히려 좋은 인상을 남길 수 있습니다."]} },
        moving: { upright: {"a":["익숙하고 안정적인, 검증된 곳으로의 이동이 잘 맞는 시기입니다.","평판이 좋은 동네로 옮기는 것이 마음을 편안하게 해주는 시기입니다.","많은 사람이 선택해온 지역일수록 안심이 되는 시기입니다."],"b":["낯선 곳보다 이미 검증된 곳을 택하는 것이 마음도 편안합니다.","잘 모르는 동네보다 평판이 좋은 곳을 우선 알아보세요.","주변의 추천을 참고해서 이사할 곳을 정해보는 것도 좋습니다."]}, reversed: {"a":["낯선 변화에 대한 거부감이 필요한 이동을 지연시킬 수 있습니다.","새로운 동네에 대한 막연한 두려움이 이사를 자꾸 미루게 만들 수 있는 시기입니다.","지금 사는 곳을 떠나기 아쉬운 마음이 이사 결정을 계속 늦추게 만듭니다."],"b":["익숙함에서 벗어나기 두렵더라도 변화를 받아들일 필요가 있습니다.","두려운 마음이 들어도 한 걸음씩 움직여보세요.","낯선 곳에 대한 걱정은 직접 가보면 줄어들 수 있습니다."]} },
        children: { upright: {"a":["전통적인 가치관으로 아이를 교육하며 안정감을 주는 시기입니다.","예로부터 이어온 지혜를 아이에게 자연스럽게 물려주는 시기입니다.","검증된 육아 방식을 따르는 것이 마음에 안정을 주는 시기입니다."],"b":["일관된 가치관이 아이에게 안정적인 기준이 되어줍니다.","어른들의 경험에서 나온 지혜를 아이에게 나눠주세요.","믿을 만한 육아서나 전문가의 조언을 참고해보는 것도 좋습니다."]}, reversed: {"a":["정해진 방식만 고집하다 아이의 개성과 부딪힐 수 있는 시기입니다.","늘 해오던 훈육법이 지금의 아이 성향과는 맞지 않을 수 있는 시기입니다.","정해둔 틀에 맞추려는 마음이 아이와의 사이에 벽을 만들 수 있습니다."],"b":["아이의 개성도 존중하며 조금은 유연하게 대해주세요.","아이만의 속도와 방식을 존중하는 여유가 필요합니다.","정해둔 기준을 살짝 내려놓고 눈앞의 아이를 있는 그대로 바라봐주세요."]} }
